{
  "name": "带ROI统计功能的面阵探测器",
  "name_en": "Area Detector with ROI Statistics",
  "manufacturer": "",
  "description": "用于实验成像的面阵探测器系统，可采集二维图像并对感兴趣区域（ROI）进行强度或计数统计。常用于同步辐射束线、X射线成像和通用扫描实验中的在线监测、快门联动与文件存储。",
  "description_en": "A 2D area detector system for experimental imaging that acquires images and computes intensity or count statistics in selected regions of interest (ROIs). It is commonly used in beamline, X-ray, and general scan-based experiments for online monitoring, shutter coordination, and file saving.",
  "actions": [
    {
      "action_name": "auto-arm",
      "description": "预备探测器进入采集就绪状态。",
      "description_en": "Arm the detector for acquisition."
    },
    {
      "action_name": "auto-start",
      "description": "开始采集数据。",
      "description_en": "Start data acquisition."
    },
    {
      "action_name": "auto-stop",
      "description": "停止采集数据。",
      "description_en": "Stop data acquisition."
    },
    {
      "action_name": "auto-config_filesaver",
      "description": "配置文件保存参数。",
      "description_en": "Configure file-saving parameters."
    },
    {
      "action_name": "auto-filePut",
      "description": "设置文件保存相关参数。",
      "description_en": "Set a file-saving related parameter."
    },
    {
      "action_name": "auto-fileGet",
      "description": "获取文件保存相关参数。",
      "description_en": "Get a file-saving related parameter."
    },
    {
      "action_name": "auto-setFilePath",
      "description": "设置文件保存路径。",
      "description_en": "Set the file save path."
    },
    {
      "action_name": "auto-setFileTemplate",
      "description": "设置文件名模板。",
      "description_en": "Set the file naming template."
    },
    {
      "action_name": "auto-setFileWriteMode",
      "description": "设置文件写入模式。",
      "description_en": "Set the file write mode."
    },
    {
      "action_name": "auto-setFileName",
      "description": "设置文件名。",
      "description_en": "Set the file name."
    },
    {
      "action_name": "auto-nextFileNumber",
      "description": "递增文件编号。",
      "description_en": "Advance to the next file number."
    },
    {
      "action_name": "auto-setFileNumber",
      "description": "设置文件编号。",
      "description_en": "Set the file number."
    },
    {
      "action_name": "auto-getLastFileName",
      "description": "获取最近一次保存的文件名。",
      "description_en": "Get the last saved file name."
    },
    {
      "action_name": "auto-getNumCapture",
      "description": "获取设定的捕获数量。",
      "description_en": "Get the configured number of captures."
    },
    {
      "action_name": "auto-getNumCaptured_RBV",
      "description": "获取实际已捕获数量。",
      "description_en": "Get the actual number of captures completed."
    },
    {
      "action_name": "auto-FileCaptureOn",
      "description": "开启文件捕获。",
      "description_en": "Enable file capture."
    },
    {
      "action_name": "auto-FileCaptureOff",
      "description": "关闭文件捕获。",
      "description_en": "Disable file capture."
    },
    {
      "action_name": "auto-setFileNumCapture",
      "description": "设置文件捕获数量。",
      "description_en": "Set the number of captures for file saving."
    },
    {
      "action_name": "auto-FileWriteComplete",
      "description": "获取文件写入完成状态。",
      "description_en": "Get the file write completion status."
    },
    {
      "action_name": "auto-getFileTemplate",
      "description": "获取文件名模板。",
      "description_en": "Get the file naming template."
    },
    {
      "action_name": "auto-getFileName",
      "description": "获取文件名。",
      "description_en": "Get the file name."
    },
    {
      "action_name": "auto-getFileNumber",
      "description": "获取文件编号。",
      "description_en": "Get the file number."
    },
    {
      "action_name": "auto-getFilePath",
      "description": "获取文件保存路径。",
      "description_en": "Get the file save path."
    },
    {
      "action_name": "auto-getFileNameByIndex",
      "description": "按索引获取文件名。",
      "description_en": "Get the file name by index."
    },
    {
      "action_name": "auto-getNextFileName",
      "description": "获取下一个文件名。",
      "description_en": "Get the next file name."
    },
    {
      "action_name": "auto-config_shutter",
      "description": "配置快门控制参数。",
      "description_en": "Configure shutter control parameters."
    },
    {
      "action_name": "auto-open_shutter",
      "description": "打开快门。",
      "description_en": "Open the shutter."
    },
    {
      "action_name": "auto-close_shutter",
      "description": "关闭快门。",
      "description_en": "Close the shutter."
    },
    {
      "action_name": "auto-get_next_filename",
      "description": "获取下一个文件名。",
      "description_en": "Get the next file name."
    },
    {
      "action_name": "auto-pre_scan",
      "description": "为扫描采集做准备。",
      "description_en": "Prepare the detector for scan acquisition."
    },
    {
      "action_name": "auto-post_scan",
      "description": "完成扫描后恢复或收尾。",
      "description_en": "Finalize or restore the detector after a scan."
    },
    {
      "action_name": "auto-ContinuousMode",
      "description": "设置为连续采集模式。",
      "description_en": "Set the acquisition mode to continuous."
    },
    {
      "action_name": "auto-ScalerMode",
      "description": "设置为标量计数模式。",
      "description_en": "Set the acquisition mode to scaler counting."
    },
    {
      "action_name": "auto-ROIMode",
      "description": "设置为ROI统计模式。",
      "description_en": "Set the acquisition mode to ROI statistics."
    },
    {
      "action_name": "auto-NDArrayMode",
      "description": "设置为数组图像输出模式。",
      "description_en": "Set the acquisition mode to NDArray output."
    },
    {
      "action_name": "auto-set_dwelltime",
      "description": "设置驻留时间。",
      "description_en": "Set the dwell time."
    },
    {
      "action_name": "auto-disarm",
      "description": "解除采集预备状态。",
      "description_en": "Disarm the detector."
    },
    {
      "action_name": "auto-save_arraydata",
      "description": "保存数组图像数据。",
      "description_en": "Save array image data."
    },
    {
      "action_name": "auto-file_write_complete",
      "description": "获取文件写入完成状态。",
      "description_en": "Get the file write completion status."
    }
  ],
  "tag_hints": [
    "area detector",
    "ROI statistics",
    "2D imaging",
    "scan acquisition",
    "file capture",
    "shutter control",
    "X-ray imaging",
    "beamline detector"
  ]
}

